arguments.query:
SELECT time, pid, ppid, pname, process_name, access, object, event_record_id, event_id, subject_user_name, command_line, alert_name, alert_reason, alert_category, netconn_domain, remote_ip, remote_port
FROM audit_logs
WHERE pid = 4572 AND pname = 'winword.exe' AND time > '2022-07-20 00:45:30' AND (access IN ('read', 'write', 'connect') OR regmod_name IS NOT NULL OR filemod_name IS NOT NULL OR netconn_domain IS NOT NULL OR remote_ip IS NOT NULL);
